function heaviestRisingRun(nums: number[]): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let sum = nums[i];
    best = Math.max(best, sum);
    for (let j = i + 1; j < nums.length && nums[j] > nums[j - 1]; j++) {
      sum += nums[j];
      best = Math.max(best, sum);
    }
  }
  return best;
}

