class Solution:
    def heaviestRisingRun(self, nums: List[int]) -> int:
        best = 0
        for i in range(len(nums)):
            total = nums[i]
            best = max(best, total)
            j = i + 1
            while j < len(nums) and nums[j] > nums[j - 1]:
                total += nums[j]
                best = max(best, total)
                j += 1
        return best

